// Package gogen compiles a checked Herta program to Go source that calls
// hertasdk. See herta/docs/CODEGEN.md for the mapping.
//
// Handler bodies are emitted almost verbatim: statements are opaque text in
// the AST, so the generated file expects the surrounding package to provide
// the types and helper functions the bodies reference. The only rewrite is
// `fail <outcome>, <expr>`, which becomes
// `return *new(T), hertasdk.Fail(hertasdk.<Outcome>, <expr>)` — a classified
// failure return, matching the language spec.
package gogen

import (
	"fmt"
	"go/format"
	"strconv"
	"strings"
	"unicode"

	"github.com/arahe-dev/hertasdk/herta/lang"
)

// Generate renders prog as a Go source file in package pkg. The program must
// already have passed lang.Check — the emitted code assumes the contracts
// hold and does not re-validate them.
func Generate(prog *lang.Program, pkg string) (string, error) {
	var b strings.Builder
	fmt.Fprintf(&b, "// Code generated by herta build; DO NOT EDIT.\n\npackage %s\n\n", pkg)

	// Imports: context for handler signatures, time for timeout clauses,
	// hertasdk always.
	needTime := false
	for _, d := range prog.Decls {
		if op, ok := d.(*lang.Op); ok && op.Timeout != "" {
			needTime = true
		}
	}
	b.WriteString("import (\n\t\"context\"\n")
	if needTime {
		b.WriteString("\t\"time\"\n")
	}
	b.WriteString("\n\t\"github.com/arahe-dev/hertasdk\"\n)\n\n")

	handlers := map[string]*lang.Handler{}
	for _, d := range prog.Decls {
		if h, ok := d.(*lang.Handler); ok {
			handlers[h.Runtime+"::"+h.Name] = h
		}
	}

	for _, d := range prog.Decls {
		switch d := d.(type) {
		case *lang.Runtime:
			genRuntime(&b, d)
		case *lang.Op:
			if err := genOp(&b, d, handlers[d.Runtime+"::"+d.Name]); err != nil {
				return "", err
			}
		}
	}

	out, err := format.Source([]byte(b.String()))
	if err != nil {
		return "", fmt.Errorf("generated source did not format: %w", err)
	}
	return string(out), nil
}

// genRuntime emits one constructor per runtime:
//
//	func NewMainRuntime() (*hertasdk.Runtime, error)
func genRuntime(b *strings.Builder, rt *lang.Runtime) {
	fmt.Fprintf(b, "// New%sRuntime constructs runtime %q with its declared resource budgets.\n", export(rt.Name), rt.Name)
	fmt.Fprintf(b, "func New%sRuntime() (*hertasdk.Runtime, error) {\n", export(rt.Name))
	b.WriteString("\treturn hertasdk.NewRuntime(\n")
	for _, r := range rt.Resources {
		fmt.Fprintf(b, "\t\thertasdk.ResourceSpec{Name: %s, Capacity: %d},\n", strconv.Quote(r.Name), r.Capacity)
	}
	b.WriteString("\t)\n}\n\n")
}

// genOp emits, per op main::charge:
//
//	type MainChargeInput struct{ UserId string; Cents uint64 }
//	func NewMainCharge(rt *hertasdk.Runtime) (*hertasdk.Operation[MainChargeInput, receipt], error)
//	func mainChargeHandler(ctx context.Context, in MainChargeInput) (receipt, error)
func genOp(b *strings.Builder, op *lang.Op, h *lang.Handler) error {
	base := export(op.Runtime) + export(op.Name)
	input := base + "Input"
	result := goType(op.Result)

	// The call input struct: one exported field per op parameter.
	fmt.Fprintf(b, "// %s is the input of op %s::%s.\n", input, op.Runtime, op.Name)
	fmt.Fprintf(b, "type %s struct {\n", input)
	for _, p := range op.Params {
		fmt.Fprintf(b, "\t%s %s\n", export(p.Name), goType(p.Type))
	}
	b.WriteString("}\n\n")

	// The constructor assembles the Policy exactly as declared.
	fmt.Fprintf(b, "// New%s constructs op %s::%s on rt.\n", base, op.Runtime, op.Name)
	fmt.Fprintf(b, "func New%s(rt *hertasdk.Runtime) (*hertasdk.Operation[%s, %s], error) {\n", base, input, result)
	fmt.Fprintf(b, "\treturn hertasdk.NewOperation(rt, %s, %s, hertasdk.Policy[%s]{\n",
		strconv.Quote(op.Runtime+"::"+op.Name), handlerName(op), input)
	fmt.Fprintf(b, "\t\tEffect: hertasdk.%s,\n", sdkEffect(op.Effect))
	if op.Admission == "reject" {
		b.WriteString("\t\tAdmission: hertasdk.Reject,\n")
	}
	if len(op.Resources) > 0 {
		b.WriteString("\t\tResources: []hertasdk.Requirement{\n")
		for _, r := range op.Resources {
			fmt.Fprintf(b, "\t\t\t{Name: %s, Units: %d},\n", strconv.Quote(r.Name), r.Units)
		}
		b.WriteString("\t\t},\n")
	}
	if op.Timeout != "" {
		d, err := durationExpr(op.Timeout)
		if err != nil {
			return err
		}
		fmt.Fprintf(b, "\t\tTimeout: %s,\n", d)
	}
	if op.Key != "" {
		fmt.Fprintf(b, "\t\tSerializeKey: func(in %s) string { return in.%s },\n", input, export(op.Key))
	}
	if op.Retry != nil {
		fmt.Fprintf(b, "\t\tRetry: hertasdk.RetryPolicy{\n\t\t\tMaxAttempts: %d,\n", op.Retry.Max)
		b.WriteString("\t\t\tOn: map[hertasdk.Outcome]bool{\n")
		for _, o := range op.Retry.On {
			fmt.Fprintf(b, "\t\t\t\thertasdk.%s: true,\n", export(o.Name))
		}
		b.WriteString("\t\t\t},\n\t\t},\n")
	}
	b.WriteString("\t})\n}\n\n")

	// The handler wrapper unpacks the input fields so the body text can
	// refer to parameters by name, then emits the body with `fail`
	// rewritten to classified-error returns.
	if h == nil {
		return fmt.Errorf("op %s::%s has no handler", op.Runtime, op.Name)
	}
	fmt.Fprintf(b, "func %s(ctx context.Context, in %s) (%s, error) {\n", handlerName(op), input, result)
	b.WriteString("\t_ = ctx\n")
	for _, p := range op.Params {
		fmt.Fprintf(b, "\t%s := in.%s\n", p.Name, export(p.Name))
	}
	for _, s := range h.Body {
		genStmt(b, s, result)
	}
	b.WriteString("}\n\n")
	return nil
}

func handlerName(op *lang.Op) string {
	return unexport(op.Runtime) + export(op.Name) + "Handler"
}

// genStmt emits one handler-body statement. FailStmt is `fail o, e`, a
// classified-error return. RawStmt is emitted verbatim except inline `fail`
// uses, which get the same rewrite.
func genStmt(b *strings.Builder, s lang.Stmt, result string) {
	switch s := s.(type) {
	case *lang.FailStmt:
		fmt.Fprintf(b, "\treturn *new(%s), hertasdk.Fail(hertasdk.%s, %s)\n", result, export(s.Outcome), s.Arg)
	case *lang.RawStmt:
		for _, line := range rewriteFails(s.Text, result) {
			fmt.Fprintf(b, "\t%s\n", line)
		}
	}
}

// rewriteFails turns `fail <outcome>, <expr>` inside preserved body text
// into `return *new(T), hertasdk.Fail(hertasdk.<Outcome>, <expr>)`. The text
// is token-joined source on one logical line, so the expression runs to a
// top-level `}` or `;`, or to the end of the text.
func rewriteFails(text, result string) []string {
	var out strings.Builder
	i := 0
	for i < len(text) {
		// Skip string and char literals: `fail` inside quotes is data.
		if c := text[i]; c == '"' || c == '\'' {
			j := i + 1
			for j < len(text) && text[j] != c {
				if text[j] == '\\' {
					j++
				}
				j++
			}
			out.WriteString(text[i:min(j+1, len(text))])
			i = j + 1
			continue
		}
		// A fail statement starts at a statement boundary.
		if strings.HasPrefix(text[i:], "fail ") || strings.HasPrefix(text[i:], "fail\t") {
			boundary := i == 0
			if !boundary {
				prev := i - 1
				for prev >= 0 && (text[prev] == ' ' || text[prev] == '\t') {
					prev--
				}
				boundary = prev < 0 || text[prev] == '{' || text[prev] == ';' || text[prev] == ':'
			}
			if boundary {
				i = rewriteOneFail(&out, text, i, result)
				continue
			}
		}
		out.WriteByte(text[i])
		i++
	}
	return []string{out.String()}
}

// rewriteOneFail consumes `fail <outcome>, <expr>` at position i in text
// and writes the classified-error return. The expression ends at a
// top-level `}` or `;` or at end of text.
func rewriteOneFail(out *strings.Builder, text string, i int, result string) int {
	j := i + len("fail")
	for j < len(text) && (text[j] == ' ' || text[j] == '\t') {
		j++
	}
	start := j
	for j < len(text) && (unicode.IsLetter(rune(text[j])) || text[j] == '_') {
		j++
	}
	outcome := text[start:j]
	for j < len(text) && (text[j] == ' ' || text[j] == '\t') {
		j++
	}
	if j >= len(text) || text[j] != ',' {
		// Not a fail statement after all (e.g. a function named fail);
		// copy through verbatim.
		out.WriteString(text[i:j])
		return j
	}
	j++
	for j < len(text) && (text[j] == ' ' || text[j] == '\t') {
		j++
	}
	// Scan the expression to its boundary.
	exprStart := j
	depth := 0
	for j < len(text) {
		c := text[j]
		if c == '"' || c == '\'' {
			k := j + 1
			for k < len(text) && text[k] != c {
				if text[k] == '\\' {
					k++
				}
				k++
			}
			j = k + 1
			continue
		}
		switch c {
		case '{', '(', '[':
			depth++
		case '}', ')', ']':
			if depth == 0 {
				goto end
			}
			depth--
		case ';':
			if depth == 0 {
				goto end
			}
		}
		j++
	}
end:
	expr := strings.TrimSpace(text[exprStart:j])
	fmt.Fprintf(out, "return *new(%s), hertasdk.Fail(hertasdk.%s, %s)", result, export(outcome), expr)
	return j
}

// sdkEffect maps a Herta effect value to the hertasdk constant name.
func sdkEffect(e string) string {
	switch e {
	case "pure":
		return "Pure"
	case "idempotent":
		return "Idempotent"
	case "nonidempotent":
		return "NonIdempotent"
	}
	return e
}

// goType maps a Herta type name to Go. Language primitives map to their Go
// counterparts; any other name passes through so user-defined types in the
// surrounding package resolve.
func goType(t string) string {
	switch t {
	case "string", "bool", "byte", "rune", "error":
		return t
	case "int", "int8", "int16", "int32", "int64",
		"uint", "uint8", "uint16", "uint32", "uint64",
		"float32", "float64":
		return t
	case "i8":
		return "int8"
	case "i16":
		return "int16"
	case "i32":
		return "int32"
	case "i64":
		return "int64"
	case "u8":
		return "uint8"
	case "u16":
		return "uint16"
	case "u32":
		return "uint32"
	case "u64":
		return "uint64"
	case "f32":
		return "float32"
	case "f64":
		return "float64"
	case "bytes":
		return "[]byte"
	}
	return t
}

// durationExpr renders a Herta duration literal as a time expression:
// "500ms" -> "500 * time.Millisecond".
func durationExpr(d string) (string, error) {
	i := 0
	for i < len(d) && d[i] >= '0' && d[i] <= '9' {
		i++
	}
	if i == 0 {
		return "", fmt.Errorf("invalid duration literal %q", d)
	}
	n, unit := d[:i], d[i:]
	var u string
	switch unit {
	case "ns":
		u = "Nanosecond"
	case "us":
		u = "Microsecond"
	case "ms":
		u = "Millisecond"
	case "s":
		u = "Second"
	case "m":
		u = "Minute"
	case "h":
		u = "Hour"
	default:
		return "", fmt.Errorf("invalid duration unit in %q", d)
	}
	// Strip leading zeros so e.g. "010ms" emits decimal 10, not an octal
	// literal.
	num := strings.TrimLeft(n, "0")
	if num == "" {
		num = "0"
	}
	if num == "1" {
		return "time." + u, nil
	}
	return num + " * time." + u, nil
}

// export renders an identifier as an exported Go name: each
// underscore-separated part is title-cased (user_id -> UserId).
func export(name string) string {
	var b strings.Builder
	for _, part := range strings.Split(name, "_") {
		if part == "" {
			continue
		}
		r := []rune(part)
		b.WriteRune(unicode.ToUpper(r[0]))
		b.WriteString(string(r[1:]))
	}
	return b.String()
}

func unexport(name string) string {
	r := []rune(export(name))
	if len(r) == 0 {
		return name
	}
	r[0] = unicode.ToLower(r[0])
	return string(r)
}
